            control: ctl_tx,
            modules: Arc::new(Mutex::new(vec!["admin".into(), "users".into()])),
            module_admin: None,
            events: Arc::new(Mutex::new(EventLog::default())),
        };
        (state, receivers, ctl_rx)
    }

    #[test]
    fn say_enqueues_privmsg_on_named_server() {
