    #[test]
    fn say_omits_server_when_single_network() {
        let (state, mut rx, _ctl) = state_with(&["only"]);
        let out = dispatch(&state, "say", "#room hi");
        assert!(out[0].contains("on only"), "{out:?}");
        assert!(matches!(
            rx.get_mut("only").unwrap().try_recv().unwrap(),
            IrcAction::Privmsg { .. }
        ));
    }

    #[test]
    fn say_requires_server_when_multiple() {
        let (state, _rx, _ctl) = state_with(&["a", "b"]);
        let out = dispatch(&state, "say", "#room hi");
        assert!(out[0].contains("specify a network"), "{out:?}");
    }

    #[test]
    fn wordle_requires_network_when_multiple_and_valid_arguments() {
        let (state, _rx, _ctl) = state_with(&["a", "b"]);
        let out = dispatch(&state, "wordle", "notziggy new");
        assert!(out[0].contains("specify a network"), "{out:?}");

        let (state, _rx, _ctl) = state_with(&["a"]);
        let out = dispatch(&state, "wordle", "notziggy");
        assert!(out[0].contains("usage:"), "{out:?}");
    }

    #[test]
    fn ignore_and_unignore_use_the_stable_profile() {
        let (state, _rx, _ctl) = state_with(&["libera"]);
        state
            .db
            .profile_ensure_blocking("libera", "Alice", 100)
            .unwrap();
        let profile = state
            .db
            .profile_get_blocking("libera", "Alice")
            .unwrap()
            .unwrap();

        assert!(dispatch(&state, "ignore", "libera Alice")[0].contains("ignoring Alice"));
        assert!(state
            .db
            .profile_is_ignored_blocking("libera", &profile.id)
            .unwrap());
        assert!(
            dispatch(&state, "unignore", "libera Alice")[0].contains("no longer ignoring Alice")
        );
        assert!(!state
            .db
            .profile_is_ignored_blocking("libera", &profile.id)
            .unwrap());
    }

    #[test]
    fn control_commands_signal() {
        let (state, _rx, mut ctl) = state_with(&["x"]);
        dispatch(&state, "reload", "");
        assert!(matches!(ctl.try_recv().unwrap(), Control::Reload));
        dispatch(&state, "shutdown", "");
        assert!(matches!(ctl.try_recv().unwrap(), Control::Shutdown));
    }

    #[test]
    fn status_lists_networks_and_modules() {
        let (state, _rx, _ctl) = state_with(&["libera"]);
        let out = dispatch(&state, "status", "");
        assert!(out.iter().any(|l| l.contains("libera")));
        assert!(out.iter().any(|l| l.contains("admin")));
    }

    #[test]
    fn unknown_command_is_friendly() {
        let (state, _rx, _ctl) = state_with(&["x"]);
        assert!(dispatch(&state, "frobnicate", "")[0].contains("unknown command"));
    }

    #[test]
    fn event_log_since() {
        let mut log = EventLog::default();
        log.push("a".into());
        log.push("b".into());
        let after_first = log.since(1);
        assert_eq!(after_first.len(), 1);
        assert_eq!(after_first[0].1, "b");
    }
}

//! Permission resolver stage.
//!
//! Sits between the IRC actors and the module host. For each incoming message it resolves the
//! sender's role (via the DB, which also performs trust-on-first-use binding) and stamps it onto
//! the message before forwarding to the modules. Modules enforce access by checking `msg.role`.
//!
//! Identity preference: the verified services account (IRCv3 `account-tag`) when present, else the
//! `nick!user@host` hostmask bound on first contact. The actual policy lives in `db::resolve_role`.

use crate::db::DbHandle;
use crate::log_bus::LogBus;
use jeeves_abi::{Event, EventEnvelope};
use tokio::sync::mpsc;

/// Spawn the resolver. Returns the inlet the IRC actors should send events to; resolved events are
/// forwarded to `out` (the module host).
pub fn spawn(
    db: DbHandle,
    log: LogBus,
    out: mpsc::Sender<EventEnvelope>,
) -> mpsc::Sender<EventEnvelope> {
    let (tx, mut rx) = mpsc::channel::<EventEnvelope>(256);
    tokio::spawn(async move {
        while let Some(mut env) = rx.recv().await {
            if let Event::NickChanged {
                old_nick,
                new_nick,
                account,
            } = &env.event
            {
                if let Err(e) = db
                    .profile_bind_nick(&env.server, old_nick, new_nick, account.clone(), now_secs())
                    .await
                {
                    log.error("profiles", format!("nick alias update failed: {e}"));
                }
            } else if let Event::Message(msg) = &mut env.event {
                let account = msg
                    .tags
                    .iter()
                    .find(|(k, _)| k == "account")
                    .and_then(|(_, v)| v.clone())
                    .filter(|a| !a.is_empty());
                let hostmask = format!("{}!{}@{}", msg.nick, msg.user, msg.host);
                // How to address them: "{title} {nick}" if a title is set, else just the nick.
                let profile = match db
                    .profile_resolve(&env.server, &msg.nick, account.clone(), now_secs())
                    .await
                {
                    Ok(p) => {
                        msg.user_id = p.id.clone();
                        msg.display =
                            match p.title.as_deref().map(str::trim).filter(|t| !t.is_empty()) {
                                Some(title) => format!("{title} {}", msg.nick),
                                None => msg.nick.clone(),
                            };
                        Some(p)
                    }
                    Err(e) => {
                        log.error("perms", format!("profile resolution failed: {e}"));
                        msg.display = msg.nick.clone();
                        None
                    }
                };

                if let Some(profile) = &profile {
                    match db.profile_is_ignored(&env.server, &profile.id).await {
                        Ok(true) => continue,
                        Ok(false) => {}
                        Err(e) => log.error("perms", format!("ignore lookup failed: {e}")),
                    }
                }

                match db
                    .resolve_role(&env.server, &msg.nick, &hostmask, account)
                    .await
                {
                    Ok(role) => msg.role = role,
                    Err(e) => log.error("perms", format!("role resolution failed: {e}")),
                }
            }
            if out.send(env).await.is_err() {
                break;
            }
        }
    });
    tx
}

fn now_secs() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

//! Runtime supervisors for the two modes. Wires together the DB, log bus, IRC actors (one per
//! network), module host, and (in interactive mode) the TUI.

use crate::action::{AppRequest, Control, IrcAction};
use crate::adminapi::{self, AdminState, EventLog};
use crate::backup::BackupHandle;
use crate::config::ServerConfig;
use crate::db::DbHandle;
use crate::irc;
use crate::log_bus::LogBus;
use crate::modules::{self, ModuleControl, ModuleHost, ModulePaths, ServerRegistry};
use crate::perms;
use crate::publicweb::{self, PublicWebState};
use crate::theme::ThemeStore;
use crate::tui;
use anyhow::Result;
use jeeves_abi::{Category, EventEnvelope, Level};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::sync::mpsc;
use tokio::task::JoinHandle;

/// Spawn the IRC actor for `cfg`, returning its task handle and an action sender.
fn spawn_irc(
    cfg: ServerConfig,
    log: LogBus,
    events: mpsc::Sender<EventEnvelope>,
    casemappings: crate::casemapping::CaseMappingRegistry,
) -> (JoinHandle<()>, mpsc::Sender<IrcAction>) {
    let (action_tx, action_rx) = mpsc::channel(64);
    let label = cfg.label.clone();
    let handle = tokio::spawn(async move {
        let mut action_rx = action_rx;
        let mut delay = Duration::from_secs(1);
        loop {
            let started = std::time::Instant::now();
            match irc::run(
                cfg.clone(),
                log.clone(),
                &mut action_rx,
                events.clone(),
                casemappings.clone(),
            )
            .await
            {
                Ok(irc::RunExit::StopRequested) => break,
                Ok(irc::RunExit::Disconnected) => {}
                Err(e) => log.error("irc", format!("[{label}] connection ended: {e}")),
            }
            let _ = events
                .send(EventEnvelope {
                    server: label.clone(),
                    event: jeeves_abi::Event::Disconnected,
                })
                .await;
            if started.elapsed() >= Duration::from_secs(60) {
                delay = Duration::from_secs(1);
            }
            log.info(
                "irc",
                format!("[{label}] reconnecting in {}s", delay.as_secs()),
            );
            let deadline = tokio::time::Instant::now() + delay;
            loop {
                tokio::select! {
                    _ = tokio::time::sleep_until(deadline) => break,
                    action = action_rx.recv() => match action {
                        Some(IrcAction::Quit(_)) | None => return,
                        Some(action) => log.debug(
                            "irc",
                            format!("[{label}] dropped action while disconnected: {action:?}"),
                        ),
                    },
                }
            }
            delay = (delay * 2).min(Duration::from_secs(60));
        }
    });
    (handle, action_tx)
}

/// Subscribe to the log bus and persist every event to the DB.
fn spawn_db_sink(log: &LogBus, db: DbHandle) {
    let mut rx = log.subscribe();
    tokio::spawn(async move {
        while let Ok(ev) = rx.recv().await {
            let _ = db.append_log(ev).await;
        }
    });
}

/// Shared wiring used by both modes.
struct Core {
    db: DbHandle,
    log: LogBus,
    modhost: ModuleHost,
    control_rx: mpsc::Receiver<Control>,
    control_tx: mpsc::Sender<Control>,
    registry: ServerRegistry,
    /// Inlet for IRC events: the permission resolver, which enriches messages with the sender's
    /// role and forwards to the module host.
    events_in: mpsc::Sender<EventEnvelope>,
    handles: HashMap<String, JoinHandle<()>>,
    backups: BackupHandle,
}

#[derive(Clone, Copy)]
pub struct RuntimePaths<'a> {
    pub modules: &'a str,
    pub theme: &'a str,
    pub capabilities: &'a str,
    pub exports: &'a str,
    pub local_rules: Option<&'a str>,
}

impl Core {
    fn new(db: DbHandle, log: LogBus, paths: RuntimePaths<'_>) -> Self {
        spawn_db_sink(&log, db.clone());
        let backups = BackupHandle::spawn(db.clone(), log.clone());
        let registry: ServerRegistry = Arc::new(Mutex::new(HashMap::new()));
        let (control_tx, control_rx) = mpsc::channel::<Control>(32);
        let theme = ThemeStore::open(paths.theme);
        let modhost = modules::spawn(
            ModulePaths {
                modules_dir: paths.modules.into(),
                capabilities_path: paths.capabilities.into(),
                export_dir: paths.exports.into(),
                local_rules_path: paths.local_rules.map(std::path::PathBuf::from),
            },
            registry.clone(),
            control_tx.clone(),
            db.clone(),
            log.clone(),
            theme,
        );
        let events_in = perms::spawn(db.clone(), log.clone(), modhost.events.clone());
        Core {
            db,
            log,
            modhost,
            control_rx,
            control_tx,
            registry,
            events_in,
            handles: HashMap::new(),
            backups,
        }
    }

    /// Start the Discord/admin HTTP API if a token was configured. Surfaces ERROR + COMMAND log
    /// events to the API's `/v1/events` buffer.
    fn start_admin(&self, admin: Option<(String, String)>) {
        let Some((bind, token)) = admin else {
            return;
        };
        let events = Arc::new(Mutex::new(EventLog::default()));
        {
            let events = events.clone();
            let mut rx = self.log.subscribe();
            tokio::spawn(async move {
                while let Ok(ev) = rx.recv().await {
                    if matches!(ev.level, Level::Error) || matches!(ev.category, Category::Command)
                    {
                        events
                            .lock()
                            .unwrap()
                            .push(format!("[{}] {}", ev.source, ev.message));
                    }
                }
            });
        }
        let state = AdminState {
            db: self.db.clone(),
            registry: self.registry.clone(),
            control: self.control_tx.clone(),
            modules: self.modhost.names.clone(),
            module_admin: Some(self.modhost.module_admin.clone()),
            events,
        };
        adminapi::serve(bind, token, state, self.log.clone());
    }

    fn start_public_web(&self, bind: Option<String>) {
        let Some(bind) = bind else { return };
        publicweb::serve(
            bind,
            PublicWebState {
                db: self.db.clone(),
                achievements: self.modhost.achievements.clone(),
            },
            self.log.clone(),
        );
    }

    /// (Re)connect every enabled server profile. Rebuilds the action registry so module sends
    /// reach the live actors.
    async fn connect_all(&mut self) {
        let servers = match self.db.load_servers().await {
            Ok(s) => s,
            Err(e) => {
                self.log.error("main", format!("config load failed: {e}"));
                return;
            }
        };
        let enabled: Vec<ServerConfig> = servers
            .into_iter()
            .filter(|s| s.enabled && !s.host.is_empty())
            .collect();
        if enabled.is_empty() {
            self.log.info(
                "main",
                "no enabled servers configured — add one in Settings",
            );
            return;
        }
        for cfg in enabled {
            let label = cfg.label.clone();
            let (handle, action_tx) = spawn_irc(
                cfg,
                self.log.clone(),
                self.events_in.clone(),
                self.db.casemappings(),
            );
            self.registry
                .lock()
                .unwrap()
                .insert(label.clone(), action_tx);
            self.handles.insert(label, handle);
        }
    }

    async fn reconnect_all(&mut self) {
        self.quit_all().await;
        self.connect_all().await;
    }

    /// Gracefully stop all IRC actors: send QUIT to each, then wait for the connection to close
    /// (flushing the QUIT), aborting any that linger past a short grace period.
    async fn quit_all(&mut self) {
        let message = shutdown_quit_message();
        {
            let reg = self.registry.lock().unwrap();
            for tx in reg.values() {
                let _ = tx.try_send(IrcAction::Quit(Some(message.into())));
            }
        } // drop the std Mutex guard before awaiting

        for (label, mut handle) in self.handles.drain() {
            if tokio::time::timeout(Duration::from_millis(2000), &mut handle)
                .await
                .is_err()
            {
                self.log
                    .debug("main", format!("[{label}] did not QUIT in time; aborting"));
                handle.abort();
            }
        }
        self.registry.lock().unwrap().clear();
    }
}

fn shutdown_quit_message() -> &'static str {
    const MESSAGES: &[&str] = &[
        "Jeeves is polishing the silver; service will resume shortly.",
        "Jeeves withdraws to attend to the household accounts.",
        "Jeeves has been summoned below stairs.",
        "Jeeves is seeing to a small matter of service.",
    ];
    let seconds = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_secs() as usize)
        .unwrap_or(0);
    MESSAGES[seconds % MESSAGES.len()]
}

#[cfg(unix)]
async fn terminate_signal() {
    match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
        Ok(mut signal) => {
            let _ = signal.recv().await;
        }
        Err(_) => std::future::pending::<()>().await,
    }
}

#[cfg(not(unix))]
async fn terminate_signal() {
    std::future::pending::<()>().await
}

/// Headless: connect and run, logging to stdout and the DB until ctrl-c, disconnect, or a module
/// requests shutdown.
pub async fn run_headless(
    db: DbHandle,
    log: LogBus,
    paths: RuntimePaths<'_>,
    admin: Option<(String, String)>,
    public_bind: Option<String>,
) -> Result<()> {
    // Stdout sink.
    {
        let mut rx = log.subscribe();
        tokio::spawn(async move {
            while let Ok(ev) = rx.recv().await {
                println!(
                    "[{}] {:<7} {:<8} {}: {}",
                    ev.ts,
                    level_str(ev.level),
                    cat_str(ev.category),
                    ev.source,
                    ev.message
                );
            }
        });
    }

    let mut core = Core::new(db, log.clone(), paths);
    core.start_admin(admin);
    core.start_public_web(public_bind);
    core.connect_all().await;

    loop {
        tokio::select! {
            ctl = core.control_rx.recv() => {
                match ctl {
                    Some(Control::Reload) => { let _ = core.modhost.control.send(ModuleControl::Reload).await; }
                    Some(Control::Refresh) => core.reconnect_all().await,
                    Some(Control::Shutdown) | None => {
                        log.info("main", "shutting down (module request)");
                        break;
                    }
                }
            }
            _ = tokio::signal::ctrl_c() => {
                log.info("main", "shutting down (ctrl-c)");
                break;
            }
            _ = terminate_signal() => {
                log.info("main", "shutting down (signal)");
                break;
            }
        }
    }
    core.quit_all().await;
    Ok(())
}

/// Interactive: launch the TUI and supervise the IRC connections + modules in the background.
pub async fn run_interactive(
    db: DbHandle,
    log: LogBus,
    paths: RuntimePaths<'_>,
    admin: Option<(String, String)>,
    public_bind: Option<String>,
    no_connect: bool,
) -> Result<()> {
    // Bridge log bus -> TUI (std channel the blocking TUI thread can drain).
    let (tui_log_tx, tui_log_rx) = std::sync::mpsc::channel();
    {
        let mut rx = log.subscribe();
        tokio::spawn(async move {
            while let Ok(ev) = rx.recv().await {
                if tui_log_tx.send(ev).is_err() {
                    break;
                }
            }
        });
    }

    let (app_tx, mut app_rx) = mpsc::channel::<AppRequest>(32);

    let mut core = Core::new(db.clone(), log.clone(), paths);
    core.start_public_web(public_bind);

    let tui_handle = {
        let app_tx = app_tx.clone();
        let db = db.clone();
        let log = log.clone();
        let commands = core.modhost.commands.clone();
        let settings = core.modhost.settings.clone();
        let scheduler = core.modhost.scheduler.clone();
        let backups = core.backups.clone();
        let profile_admin = core.modhost.profile_admin.clone();
        tokio::task::spawn_blocking(move || {
            tui::run(
                db,
                log,
                tui_log_rx,
                app_tx,
                tui::Services {
                    commands,
                    settings,
                    scheduler,
                    backups,
                    profile_admin,
                },
            )
        })
    };
    core.start_admin(admin);
    if !no_connect {
        core.connect_all().await;
    }

    loop {
        tokio::select! {
            req = app_rx.recv() => match req {
                Some(AppRequest::Reconnect) => core.reconnect_all().await,
                Some(AppRequest::Shutdown) | None => break,
            },
            ctl = core.control_rx.recv() => match ctl {
                Some(Control::Reload) => { let _ = core.modhost.control.send(ModuleControl::Reload).await; }
                Some(Control::Refresh) => core.reconnect_all().await,
                Some(Control::Shutdown) => break,
                None => {}
            },
            _ = tokio::signal::ctrl_c() => break,
            _ = terminate_signal() => break,
        }
    }

    core.quit_all().await;
    let _ = tui_handle.await;
    Ok(())
}

fn level_str(l: Level) -> &'static str {
    match l {
        Level::Error => "ERROR",
        Level::Info => "INFO",
        Level::Debug => "DEBUG",
    }
}

fn cat_str(c: Category) -> &'static str {
    match c {
        Category::Error => "ERROR",
        Category::Debug => "DEBUG",
        Category::Message => "MESSAGE",
        Category::Command => "COMMAND",
    }
}

