const ECONOMY_MODULE: &str = "gacha";

host_fn!(pub award_stats(ud: HostCtx; input: String) -> String {
    let ctx = ud.get()?;
    let ctx = ctx.lock().unwrap();
    ctx.require("award_stats")?;
    let req: AwardStatsRequest = serde_json::from_str(&input)?;
    let catalogs = ctx.achievements.lock().unwrap().iter().map(|(name, manifest)| (name.clone(), manifest.clone())).collect::<Vec<_>>();
    let manifest = catalogs.iter().find(|(name, _)| name == &ctx.module).map(|(_, manifest)| manifest.clone())
        .ok_or_else(|| anyhow::anyhow!("module '{}' has no achievement manifest", ctx.module))?;
    let response = ctx.db.achievement_award_blocking(&ctx.module, manifest, catalogs, req.clone(), now_secs())?;
    if !response.unlocked.is_empty() || !response.prestige.is_empty() {
        let completion = response.unlocked.iter().any(|unlock| unlock.module == "meta" && unlock.id == "whole_shooting_match");
        let unlocks = response.unlocked.iter().map(|u| u.name.clone()).collect::<Vec<_>>();
        let prestige = response.prestige.iter().map(|p| {
            let numeral = roman_rank(p.rank);
            if numeral.is_empty() { p.name.clone() } else { format!("{} {numeral}", p.name) }
        }).collect();
        queue_achievement_announcement(ctx.clone(), &req, unlocks, prestige, completion);
    }
    Ok(serde_json::to_string(&response)?)
});

host_fn!(pub economy_balance(ud: HostCtx; input: String) -> String {
    let ctx = ud.get()?;
    let (db, req) = {
        let ctx = ctx.lock().unwrap();
        ctx.require("economy_balance")?;
        let req: EconomyBalanceRequest = serde_json::from_str(&input)?;
        (ctx.db.clone(), req)
    };
    if req.server.trim().is_empty() || req.profile_id.trim().is_empty() {
        return Err(anyhow::anyhow!("economy balance requires server and profile"));
    }
    let value = db
        .kv_get_blocking(
            ECONOMY_MODULE,
            &format!("economy:balance:{}:{}", req.server, req.profile_id),
        )?
        .unwrap_or_else(|| "0".into());
    let balance = value
        .parse::<u64>()
        .map_err(|_| anyhow::anyhow!("stored economy balance is malformed"))?;
    Ok(serde_json::to_string(&EconomyBalanceResponse { balance })?)
});

host_fn!(pub economy_award(ud: HostCtx; input: String) -> String {
    let ctx = ud.get()?;
    let (db, req) = {
        let ctx = ctx.lock().unwrap();
        ctx.require("economy_award")?;
        let req: EconomyTransactionRequest = serde_json::from_str(&input)?;
        (ctx.db.clone(), req)
    };
    if req.amount == 0 {
        return Err(anyhow::anyhow!("economy award must be positive"));
    }
    Ok(serde_json::to_string(&db.economy_change_blocking(req, false)?)?)
});

host_fn!(pub economy_spend(ud: HostCtx; input: String) -> String {
    let ctx = ud.get()?;
    let (db, req) = {
        let ctx = ctx.lock().unwrap();
        ctx.require("economy_spend")?;
        let req: EconomyTransactionRequest = serde_json::from_str(&input)?;
        (ctx.db.clone(), req)
    };
    if req.amount == 0 {
