#[cfg(test)]
mod tests {
    use super::{
        announcement_text, format_module_output, module_label, roman_rank,
        validate_channel_operator,
    };
    use jeeves_abi::{ChannelOperator, ChannelOperatorAction, ChannelOperatorMode};

    #[test]
    fn operator_actions_reject_protocol_injection() {
        let valid = ChannelOperator {
            server: "net".into(),
            channel: "#test".into(),
            action: ChannelOperatorAction::Mode {
                mode: ChannelOperatorMode::Ban,
                adding: true,
                target: "nick!*@*".into(),
            },
        };
        assert!(validate_channel_operator(&valid).is_ok());

        let injected = ChannelOperator {
            action: ChannelOperatorAction::Topic {
                topic: "normal\r\nOPER bad".into(),
            },
            ..valid
        };
        assert!(validate_channel_operator(&injected).is_err());
    }

    #[test]
    fn prestige_rank_omits_one_and_uses_roman_numerals_afterward() {
        assert_eq!(roman_rank(1), "");
        assert_eq!(roman_rank(2), "II");
        assert_eq!(roman_rank(49), "XLIX");
    }

    #[test]
    fn bundled_announcements_show_three_names_and_count_the_rest() {
        let mut pending = super::super::PendingAchievementAnnouncement {
            server: "net".into(),
            target: "#test".into(),
            display_name: "nick".into(),
            unlocks: vec!["One".into(), "Two".into(), "Three".into()],
            prestige: vec!["Master II".into(), "Master III".into()],
            completion: true,
        };
        let (key, _, names, more) = announcement_text(&mut pending);
        assert_eq!(key, "completion");
        assert_eq!(names, "One, Two, Three");
        assert_eq!(more, " and 2 more");
    }

    #[test]
    fn colored_module_label_keeps_a_plain_text_fallback() {
        assert_eq!(
            format_module_output("fishing", "blue", "You caught a carp.".into()),
            "\u{3}12[Fishing]\u{f} You caught a carp."
        );
        assert_eq!(
            format_module_output("fishing", "none", "You caught a carp.".into()),
            "You caught a carp."
        );
        assert_eq!(module_label("road_trip"), "Road Trip");
        assert_eq!(module_label("ai"), "AI");
    }
}

//! SQLite persistence behind an actor task.
//!
//! `rusqlite` is synchronous, so a single [`rusqlite::Connection`] lives on a dedicated OS thread
//! and is the *only* thing that touches the database. Async callers talk to it through
//! [`DbHandle`], which sends [`DbRequest`]s over a channel and awaits a oneshot reply.

use crate::casemapping::{CaseMapping, CaseMappingRegistry};
use crate::commands::AliasOverrides;
use crate::config::{AdminEntry, ServerConfig};
use crate::log_bus::LogEvent;
use crate::settings::{scope_name, SettingOverride};
use anyhow::{anyhow, Result};
